"""Build flash-resident settings option masks from the vendored vector sources."""
from pathlib import Path
import io
import resvg_py
from PIL import Image

root = Path(__file__).resolve().parents[2]
lines = ["#pragma once", "#include <FreeInkUI.h>",
         "// Generated by tools_local/settings_art/build_option_icons.py; see assets_local/settings-icons/NOTICE.",
         "// clang-format off", "namespace settingsicons {"]


def emit_mask(name, image):
    size = image.width
    mask = [sum((image.getpixel((x + bit, y)) >= 180) << (7 - bit) for bit in range(8))
            for y in range(size) for x in range(0, size, 8)]
    lines.append(f"inline constexpr uint8_t {name}Bits[] = {{")
    lines.extend("  " + ", ".join(f"0x{v:02x}" for v in mask[i:i+16]) + "," for i in range(0, len(mask), 16))
    lines.extend(["};", f"inline constexpr freeink::ui::BitmapRef {name}{{{name}Bits, {size}, {size}, freeink::ui::BitmapFormat::Mask1, false}};"])


for source in sorted((root / "assets_local/settings-icons").glob("*.svg")):
    size = 64
    rasterSize = 256 if source.stem.startswith("Quick") else size
    raster = resvg_py.svg_to_bytes(svg_path=str(source), width=rasterSize, height=rasterSize, background="white")
    image = Image.open(io.BytesIO(raster)).convert("L")
    if source.stem.startswith("Quick"):
        bounds = image.point(lambda value: 255 if value < 180 else 0).getbbox()
        ink = image.crop(bounds)
        ink.thumbnail((44, 44), Image.Resampling.LANCZOS)
        image = Image.new("L", (64, 64), 255)
        image.paste(ink, ((64-ink.width)//2, (64-ink.height)//2))
    emit_mask(source.stem, image)

lines.extend(["}  // namespace settingsicons", "namespace settingsrowart {"])
# Match the reference option icons' ink extent inside the shared 64px canvas.
# Home/category illustrations retain their original sources and sizing.
for source in sorted((root / "assets_local/settings_art").glob("*.png")):
    if source.stem.endswith("Preview"):
        continue
    image = Image.open(source).convert("L")
    bounds = image.point(lambda value: 255 if value < 180 else 0).getbbox()
    if not bounds:
        raise ValueError(f"Empty option icon: {source.name}")
    ink = image.crop(bounds)
    ink.thumbnail((44, 44), Image.Resampling.LANCZOS)
    canvas = Image.new("L", (64, 64), 255)
    canvas.paste(ink, ((64 - ink.width) // 2, (64 - ink.height) // 2))
    emit_mask(source.stem, canvas)
lines.extend(["}  // namespace settingsrowart", "// clang-format on"])
(root / "src/apps_local/ui/SettingsOptionIcons.h").write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")
